style.css:
@-moz-document domain("docs.google.com") {
body, .kix-appview-editor, .docs-texteventtarget-iframe {
    background-image: url("https://i.pinimg.com/736x/df/e9/f2/dfe9f2901c2a52293ebf78cb7ff4616a.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center;
  }

  /* Biar teks dokumen tetap kebaca */
  .kix-page {
    background: rgba(255, 255, 255, 0.75) !important;
    border-radius: 12px;
    backdrop-filter: blur(4px);
  }
}
